import{z as n,x as A,o as E,c as d,q as l,j as i,D as e,d as r,s as o,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"外存算法与 I/O 模型","description":"","frontmatter":{"title":"外存算法与 I/O 模型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/external-memory-model.md","filePath":"cs/external-memory-model.md","lastUpdated":1791063341000}'),p={name:"cs/external-memory-model.md"};function m(C,a,F,h,c,D){const B=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=l('<h1 id="外存算法与-i-o-模型" tabindex="-1">外存算法与 I/O 模型 <a class="header-anchor" href="#外存算法与-i-o-模型" aria-label="Permalink to &quot;外存算法与 I/O 模型&quot;">​</a></h1><div class="epigraph"><p>内存 $M$、块 $B$，代价是块传输次数；排序 $\\Theta(\\frac{N}{B}\\log_{M/B}\\frac{N}{B})$ 次 I/O，不是 RAM 的 $n\\log n$ 比较。</p><footer>—— 据 Aggarwal and Vitter, The Input/Output Complexity of Sorting and Related Problems, 1988；Vitter 外存算法综述整理</footer></div><p>上一课<a href="/cs/misra-gries">Misra–Gries</a>假定流过 CPU。数据在盘上：随机访问一次块与扫一块同量级贵。缺口是 I/O 模型：扫描 \\(O(N/B)\\)，排序多路归并。不重写 RAM 快排。后课 PRAM 是并行，不是盘。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>参数 \\(N,M,B\\)，常 \\(M\\gg B\\)。扫描顺序文件最优。排序：\\(\\Theta(M/B)\\) 路归并，I/O 如题记。B 树、外存优先队列、缓存无关模型（<a href="/cs/cache-oblivious">cache-oblivious</a> 若已写则引用）点名。图外存更难（边定向）。</p><p>缺口是计数 I/O，不是 CPU 比较下界（后课对手）。<span class="marginnote">数字实例：顺序扫 100 GB 盘约几分钟；若改成逐条随机 4 KiB 读，\\(100\\,\\text{GB}\\div 4\\,\\text{KiB}\\approx 2.4\\times 10^7\\) 次，按每次 0.1 ms 算就是约 40 分钟。同一批数据，访问模式一换，时间差了好几倍——这正是模型只数「块传输次数」的原因。</span></p><h3 id="不是「内存不够就虚拟内存」" tabindex="-1">不是「内存不够就虚拟内存」 <a class="header-anchor" href="#不是「内存不够就虚拟内存」" aria-label="Permalink to &quot;不是「内存不够就虚拟内存」&quot;">​</a></h3><p>OS 分页是 LRU 在线；算法应显式扫块。虚拟内存可能抖动。外存算法自己安排传输。</p><p><span class="marginnote">Aggarwal–Vitter 1988。Vitter 综述。后课 PRAM 前缀和。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>顺序扫描、多路归并、分块矩阵乘（块 \\(B^{1/2}\\)）。图：扫描边列表多次，避免随机点。</p>',11)),(E(),i(s,null,{default:e(()=>[o(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DISK%5B%22N%20%E6%9D%A1%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20BLK%5B%22%E5%9D%97%20B%22%5D%0A%20%20BLK%20--%3E%20SORT%5B%22%E5%A4%9A%E8%B7%AF%E5%BD%92%E5%B9%B6%20I%2FO%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"缓存无关：不把 \\(B\\) 写入代码，用递归分治。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"传输一次 \\(B\\) 个元素均摊。比较在内存免费（相对 I/O）。与流：流 \\(B=1\\) 或单次扫描；外存可多遍但要少遍。与 CH：路网可外存预处理。",-1)),(E(),i(s,null,{default:e(()=>[o(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E7%9B%98%E4%B8%8A%20N%20%E6%9D%A1%E4%B9%B1%E5%BA%8F%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20RUN%5B%22%E7%AC%AC%E4%B8%80%E9%81%8D%EF%BC%9A%E6%AF%8F%E6%AC%A1%E8%A3%85%20M%20%E6%9D%A1%E8%BF%9B%E5%86%85%E5%AD%98%E6%8E%92%E5%BA%8F%EF%BC%8C%E5%86%99%E5%87%BA%20N%2FM%20%E4%B8%AA%E6%9C%89%E5%BA%8F%E6%AE%B5%22%5D%0A%20%20RUN%20--%3E%20MG%5B%22%E6%AF%8F%E4%B8%80%E9%81%8D%E5%BD%92%E5%B9%B6%EF%BC%9A%E5%90%8C%E6%97%B6%E6%89%93%E5%BC%80%20M%2FB%20%E4%B8%AA%E6%AE%B5%EF%BC%8C%E5%90%84%E5%8F%96%E6%9C%80%E5%B0%8F%22%5D%0A%20%20MG%20--%3E%20DEC%5B%22%E6%AE%B5%E6%95%B0%E6%AF%8F%E9%81%8D%E9%99%A4%E4%BB%A5%20M%2FB%EF%BC%8C%E6%AF%8F%E9%81%8D%20I%2FO%20%E4%B8%BA%20O(N%2FB)%22%5D%0A%20%20DEC%20--%3E%20FIN%7B%22%E5%8F%AA%E5%89%A9%E4%B8%80%E4%B8%AA%E6%9C%89%E5%BA%8F%E6%AE%B5%EF%BC%9F%22%7D%0A%20%20FIN%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E7%BB%A7%E7%BB%AD%E4%B8%8B%E4%B8%80%E9%81%8D%22%7C%20MG%0A%20%20FIN%20--%3E%7C%22%E6%98%AF%22%7C%20OUT%5B%22%E5%AE%8C%E6%88%90%EF%BC%9A%E6%80%BB%20I%2FO%20%E7%BA%A6%E4%B8%BA%E9%81%8D%E6%95%B0%20%C3%97%20N%2FB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">直觉类比：多路归并像在一张小桌子上整理扑克——桌面（内存 \\(M\\)）一次只能摊开 \\(M/B\\) 堆牌，每堆各翻最上面一张、挑最小的放走；堆的「路数」受桌面宽度限制，所以 \\(M/B\\) 直接决定要来回几趟。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写并行盘阵列全文。不写具体文件系统。后课默认：大数据排序用 I/O 公式。下一课 PRAM 与前缀和。<span class="marginnote">常见误区：初学者容易以为「内存装不下，交给虚拟内存就行」；但换页由 OS 的 LRU 盲目决定，算法的访问模式它看不见，容易来回抖动。外存算法的要义是自己按块安排读写，把 I/O 次数当成显式代价来优化。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代价是块 I/O；\\(M,B\\) 是参数。</li><li>外存排序多路归并。</li><li>随机访问按块计，极贵。</li><li>出处：Aggarwal and Vitter, 1988。</li></ul>',5))])}const M=n(p,[["render",m]]);export{f as __pageData,M as default};
